import pathlib
p = pathlib.Path('src/main/java/com/example/fpvdrone/event/ClientEvents.java')
p.parent.mkdir(parents=True, exist_ok=True)
p.write_text('package com.example.fpvdrone.event;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport com.example.fpvdrone.client.ClientDroneState;\nimport com.example.fpvdrone.client.gui.FpvHudOverlay;\nimport com.example.fpvdrone.client.renderer.FpvDroneRenderer;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport com.example.fpvdrone.network.C2SDroneControlPacket;\nimport com.example.fpvdrone.network.PacketHandler;\nimport com.example.fpvdrone.registry.ModEntities;\nimport com.mojang.blaze3d.vertex.PoseStack;\nimport net.minecraft.client.Minecraft;\nimport net.minecraft.client.player.Input;\nimport net.minecraft.client.renderer.LightTexture;\nimport net.minecraft.client.renderer.MultiBufferSource;\nimport net.minecraft.util.Mth;\nimport net.minecraftforge.api.distmarker.Dist;\nimport net.minecraftforge.client.event.ClientPlayerNetworkEvent;\nimport net.minecraftforge.client.event.EntityRenderersEvent;\nimport net.minecraftforge.client.event.MovementInputUpdateEvent;\nimport net.minecraftforge.client.event.RegisterGuiOverlaysEvent;\nimport net.minecraftforge.client.event.RenderGuiOverlayEvent;\nimport net.minecraftforge.client.event.RenderHandEvent;\nimport net.minecraftforge.client.event.RenderLevelStageEvent;\nimport net.minecraftforge.client.event.ViewportEvent;\nimport net.minecraftforge.event.TickEvent;\nimport net.minecraftforge.eventbus.api.SubscribeEvent;\nimport net.minecraftforge.fml.common.Mod;\nimport org.joml.Quaternionf;\nimport org.joml.Vector3f;\nimport org.lwjgl.glfw.GLFW;\n\n@Mod.EventBusSubscriber(modid = FpvDroneMod.MODID, value = Dist.CLIENT, bus = Mod.EventBusSubscriber.Bus.FORGE)\npublic class ClientEvents {\n    private static final float FPV_CAMERA_UPTILT_RAD = (float) Math.toRadians(18.0D);\n    private static double lastMouseX = Double.NaN;\n    private static double lastMouseY = Double.NaN;\n\n    @SubscribeEvent\n    public static void onClientTick(TickEvent.ClientTickEvent event) {\n        if (event.phase != TickEvent.Phase.END) {\n            return;\n        }\n        ClientDroneState.tick();\n\n        Minecraft mc = Minecraft.getInstance();\n        if (!ClientDroneState.isPiloting() || mc.player == null || mc.screen != null) {\n            lastMouseX = Double.NaN;\n            lastMouseY = Double.NaN;\n            return;\n        }\n\n        long window = mc.getWindow().getWindow();\n\n        float throttleDelta = 0.0F;\n        if (mc.options.keyUp.isDown() || mc.options.keyJump.isDown()) {\n            throttleDelta += 1.0F;\n        }\n        if (mc.options.keyDown.isDown() || GLFW.glfwGetKey(window, GLFW.GLFW_KEY_LEFT_SHIFT) == GLFW.GLFW_PRESS) {\n            throttleDelta -= 1.0F;\n        }\n\n        float yawInput = 0.0F;\n        if (mc.options.keyLeft.isDown() || GLFW.glfwGetKey(window, GLFW.GLFW_KEY_LEFT) == GLFW.GLFW_PRESS) {\n            yawInput -= 1.0F;\n        }\n        if (mc.options.keyRight.isDown() || GLFW.glfwGetKey(window, GLFW.GLFW_KEY_RIGHT) == GLFW.GLFW_PRESS) {\n            yawInput += 1.0F;\n        }\n\n        float pitchInput = 0.0F;\n        float rollInput = 0.0F;\n        double currentMouseX = mc.mouseHandler.xpos();\n        double currentMouseY = mc.mouseHandler.ypos();\n        if (!Double.isNaN(lastMouseX) && !Double.isNaN(lastMouseY)) {\n            double dx = currentMouseX - lastMouseX;\n            double dy = currentMouseY - lastMouseY;\n            if (Math.abs(dx) > 0.5D) {\n                rollInput = Mth.clamp((float) (dx * 0.032D), -1.0F, 1.0F);\n            }\n            if (Math.abs(dy) > 0.5D) {\n                pitchInput = Mth.clamp((float) (dy * 0.032D), -1.0F, 1.0F);\n            }\n        }\n        lastMouseX = currentMouseX;\n        lastMouseY = currentMouseY;\n\n        PacketHandler.sendToServer(new C2SDroneControlPacket(\n                ClientDroneState.getActiveDroneId(),\n                pitchInput,\n                rollInput,\n                yawInput,\n                throttleDelta\n        ));\n    }\n\n    @SubscribeEvent\n    public static void onMovementInputUpdate(MovementInputUpdateEvent event) {\n        if (ClientDroneState.isPilotingOrTransitioning()) {\n            Input input = event.getInput();\n            input.forwardImpulse = 0.0F;\n            input.leftImpulse = 0.0F;\n            input.up = false;\n            input.down = false;\n            input.left = false;\n            input.right = false;\n            input.jumping = false;\n            input.shiftKeyDown = false;\n        }\n    }\n\n    @SubscribeEvent\n    public static void onRenderHand(RenderHandEvent event) {\n        if (ClientDroneState.isPilotingOrTransitioning()) {\n            event.setCanceled(true);\n        }\n    }\n\n    @SubscribeEvent\n    public static void onRenderGuiOverlayPre(RenderGuiOverlayEvent.Pre event) {\n        if (ClientDroneState.isPilotingOrTransitioning()) {\n            if (!event.getOverlay().id().getNamespace().equals(FpvDroneMod.MODID)) {\n                event.setCanceled(true);\n            }\n        }\n    }\n\n    @SubscribeEvent\n    public static void onRenderLevelStage(RenderLevelStageEvent event) {\n        if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_ENTITIES) {\n            return;\n        }\n        if (!ClientDroneState.isPiloting()) {\n            return;\n        }\n        Minecraft mc = Minecraft.getInstance();\n        if (!mc.options.getCameraType().isFirstPerson()) {\n            return;\n        }\n        if (!(mc.getCameraEntity() instanceof FpvDroneEntity drone)) {\n            return;\n        }\n\n        float partialTick = event.getPartialTick();\n        Quaternionf q = drone.getInterpolatedOrientation(partialTick);\n        // Place the rendered drone rigidly in front & below the camera in drone\'s local frame\n        // so the camera is NEVER inside the model regardless of flips, rolls, or pitch\n        Vector3f localOffset = new Vector3f(0.0F, -0.34F, 0.24F).rotate(q);\n\n        PoseStack poseStack = event.getPoseStack();\n        poseStack.pushPose();\n        poseStack.translate(localOffset.x, localOffset.y, localOffset.z);\n\n        MultiBufferSource.BufferSource bufferSource = mc.renderBuffers().bufferSource();\n        mc.getEntityRenderDispatcher().render(\n                drone,\n                0.0D, 0.0D, 0.0D,\n                0.0F,\n                partialTick,\n                poseStack,\n                bufferSource,\n                LightTexture.FULL_BRIGHT\n        );\n        bufferSource.endBatch();\n        poseStack.popPose();\n    }\n\n    @SubscribeEvent\n    public static void onComputeCameraAngles(ViewportEvent.ComputeCameraAngles event) {\n        if (ClientDroneState.getPhase() == ClientDroneState.Phase.FREEZE_FRAME) {\n            event.setYaw(ClientDroneState.getLastCamYaw());\n            event.setPitch(ClientDroneState.getLastCamPitch());\n            event.setRoll(ClientDroneState.getLastCamRoll());\n            return;\n        }\n\n        if (!ClientDroneState.isPiloting()) {\n            return;\n        }\n\n        Minecraft mc = Minecraft.getInstance();\n        if (mc.getCameraEntity() instanceof FpvDroneEntity drone) {\n            Quaternionf q = drone.getInterpolatedOrientation((float) event.getPartialTick())\n                    .rotateX(-FPV_CAMERA_UPTILT_RAD);\n\n            Vector3f forward = new Vector3f(0.0F, 0.0F, 1.0F).rotate(q);\n            Vector3f localUp = new Vector3f(0.0F, 1.0F, 0.0F).rotate(q);\n            Vector3f localRight = new Vector3f(-1.0F, 0.0F, 0.0F).rotate(q);\n\n            float yaw = (float) Math.toDegrees(Math.atan2(-forward.x, forward.z));\n            float pitch = (float) -Math.toDegrees(Math.asin(Mth.clamp(forward.y, -1.0F, 1.0F)));\n\n            Vector3f worldUp = new Vector3f(0.0F, 1.0F, 0.0F);\n            Vector3f horizonRight = new Vector3f(forward).cross(worldUp);\n            float roll = 0.0F;\n            if (horizonRight.lengthSquared() > 1.0E-5F) {\n                horizonRight.normalize();\n                Vector3f horizonUp = new Vector3f(horizonRight).cross(forward).normalize();\n                roll = (float) Math.toDegrees(Math.atan2(localRight.dot(horizonUp), localRight.dot(horizonRight)));\n            } else {\n                roll = (float) Math.toDegrees(Math.atan2(localUp.x, localUp.z));\n            }\n\n            ClientDroneState.setLastCamAngles(yaw, pitch, roll);\n            event.setYaw(yaw);\n            event.setPitch(pitch);\n            event.setRoll(roll);\n        }\n    }\n\n    @SubscribeEvent\n    public static void onClientLogout(ClientPlayerNetworkEvent.LoggingOut event) {\n        ClientDroneState.resetImmediate();\n    }\n\n    @Mod.EventBusSubscriber(modid = FpvDroneMod.MODID, value = Dist.CLIENT, bus = Mod.EventBusSubscriber.Bus.MOD)\n    public static class ClientModEvents {\n        @SubscribeEvent\n        public static void onRegisterRenderers(EntityRenderersEvent.RegisterRenderers event) {\n            event.registerEntityRenderer(ModEntities.FPV_DRONE.get(), FpvDroneRenderer::new);\n        }\n\n        @SubscribeEvent\n        public static void onRegisterGuiOverlays(RegisterGuiOverlaysEvent event) {\n            event.registerAboveAll("fpv_hud", FpvHudOverlay.HUD_OVERLAY);\n        }\n    }\n}\n', encoding="utf-8")
print("Patched", p)
